contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint ts) public payable {
        uint balBefore = address(c).balance;
        uint p1 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        uint p2 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        assert(p1 <= ts && p1 == p2 && address(c).balance == balBefore);
    }
    receive() external payable {}
}

