pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 ts) internal {
        uint balBefore = address(c).balance;
        uint256 p1;
        try c.pastBlockTime() returns (uint256 __r) { p1 = __r; } catch { return; }
        uint256 p2;
        try c.pastBlockTime() returns (uint256 __r) { p2 = __r; } catch { return; }
        assertTrue(p1 <= ts && p1 == p2 && address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 ts) public {
        _run(ts);
    }

    receive() external payable {}
}
